INSERT INTO public.questions (category, subcategory, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, active) VALUES
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of adult blood pressure?', '90/60 - 120/80 mmHg', '120/80 - 140/90 mmHg', '140/90 - 160/100 mmHg', '80/60 - 100/70 mmHg', 'a', 'Normal adult BP is 90/60 to 120/80 mmHg. Hypertension is diagnosed when BP consistently exceeds 140/90 mmHg.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is best for a patient with dyspnea?', 'Supine position', 'Fowler''s position', 'Prone position', 'Lithotomy position', 'b', 'Fowler''s position (semi-sitting at 45-90 degrees) facilitates breathing by allowing maximum chest expansion in patients with dyspnea.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the first sign of hypovolemic shock?', 'Bradycardia', 'Increased blood pressure', 'Tachycardia', 'Decreased urine output', 'c', 'Tachycardia is an early compensatory mechanism in hypovolemic shock as the heart attempts to maintain cardiac output.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is used to reverse opioid overdose?', 'Flumazenil', 'Naloxone', 'Atropine', 'Epinephrine', 'b', 'Naloxone (Narcan) is a pure opioid antagonist that reverses respiratory depression caused by opioid overdose.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of fasting blood glucose?', '3.9-6.1 mmol/L', '6.1-7.0 mmol/L', '7.0-11.1 mmol/L', '2.5-3.9 mmol/L', 'a', 'Normal fasting blood glucose is 3.9-6.1 mmol/L (70-110 mg/dL). Values above 7.0 mmol/L indicate diabetes.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which vein is commonly used for IV cannulation?', 'Femoral vein', 'Cephalic vein', 'Popliteal vein', 'Subclavian vein', 'b', 'The cephalic vein in the forearm/hand is the most common site for peripheral IV cannulation due to easy accessibility.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal respiratory rate for adults?', '8-12 breaths/min', '12-20 breaths/min', '20-30 breaths/min', '30-40 breaths/min', 'b', 'Normal adult respiratory rate is 12-20 breaths per minute. Tachypnea is >20, bradypnea is <12.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which food should be avoided in a patient with celiac disease?', 'Rice', 'Wheat', 'Potato', 'Corn', 'b', 'Celiac disease requires a gluten-free diet. Wheat, barley, and rye contain gluten and must be avoided.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of acute pancreatitis?', 'Hyperlipidemia', 'Alcohol consumption', 'Trauma', 'Infection', 'b', 'Alcohol consumption and gallstones are the two most common causes of acute pancreatitis.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which assessment finding indicates deep vein thrombosis?', 'Pallor and coolness', 'Homan''s sign', 'Bounding pulse', 'Decreased sensation', 'b', 'Homan''s sign (calf pain on dorsiflexion of the foot) is a classic sign of DVT, though not always reliable.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the antidote for heparin overdose?', 'Vitamin K', 'Protamine sulfate', 'Naloxone', 'Flumazenil', 'b', 'Protamine sulfate neutralizes heparin by forming a stable salt complex. Vitamin K reverses warfarin.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which stage of pressure ulcer involves full-thickness skin loss?', 'Stage I', 'Stage II', 'Stage III', 'Stage IV', 'c', 'Stage III pressure ulcers involve full-thickness skin loss with damage to subcutaneous tissue but not fascia.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum potassium?', '3.5-5.0 mEq/L', '5.0-6.5 mEq/L', '2.0-3.5 mEq/L', '6.5-8.0 mEq/L', 'a', 'Normal serum potassium is 3.5-5.0 mEq/L. Hyperkalemia >5.0, hypokalemia <3.5.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is used for administering enema?', 'Supine', 'Prone', 'Left lateral (Sims'')', 'Right lateral', 'c', 'Left lateral (Sims'') position allows gravity to facilitate flow of enema solution into the sigmoid colon.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common nosocomial infection?', 'Surgical site infection', 'Urinary tract infection', 'Pneumonia', 'Bloodstream infection', 'b', 'UTI is the most common healthcare-associated infection, primarily due to indwelling urinary catheters.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which drug is used to treat anaphylactic shock?', 'Diphenhydramine', 'Epinephrine', 'Dopamine', 'Hydrocortisone', 'b', 'Epinephrine (1:1000, 0.3-0.5 mg IM) is the first-line treatment for anaphylaxis due to its vasoconstrictive and bronchodilatory effects.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of hemoglobin in adult males?', '10-12 g/dL', '12-14 g/dL', '13.5-17.5 g/dL', '15-20 g/dL', 'c', 'Normal hemoglobin for adult males is 13.5-17.5 g/dL. For females it is 12.0-15.5 g/dL.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which cranial nerve is tested by asking patient to shrug shoulders?', 'CN IX (Glossopharyngeal)', 'CN X (Vagus)', 'CN XI (Spinal Accessory)', 'CN XII (Hypoglossal)', 'c', 'CN XI (Spinal Accessory) innervates the trapezius and sternocleidomastoid muscles, tested by shoulder shrug and head rotation.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common symptom of myocardial infarction?', 'Epigastric pain', 'Chest pain radiating to left arm', 'Back pain', 'Jaw pain', 'b', 'Classic MI presentation is substernal chest pain/pressure radiating to left arm, neck, or jaw.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of isolation is required for tuberculosis?', 'Contact isolation', 'Droplet isolation', 'Airborne isolation', 'Standard precautions', 'c', 'TB requires airborne isolation in a negative pressure room with N95 respirator for healthcare workers.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal INR range for a patient not on anticoagulation?', '0.5-1.0', '0.8-1.2', '1.5-2.5', '2.0-3.0', 'b', 'Normal INR is 0.8-1.2. For patients on warfarin, therapeutic INR is typically 2.0-3.0.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which electrolyte imbalance is most common in burn patients?', 'Hypernatremia', 'Hyperkalemia', 'Hyponatremia', 'Hypocalcemia', 'b', 'Hyperkalemia occurs in burn patients due to cell destruction releasing intracellular potassium into circulation.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the best method to confirm NG tube placement?', 'Auscultation of air', 'pH testing of aspirate', 'X-ray', 'Bubble test', 'c', 'X-ray is the gold standard for confirming NG tube placement. pH testing and auscultation are less reliable.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which vaccine is contraindicated in pregnancy?', 'Tetanus toxoid', 'Hepatitis B', 'MMR (Measles, Mumps, Rubella)', 'Influenza', 'c', 'Live attenuated vaccines like MMR are contraindicated during pregnancy due to risk to the fetus.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of postpartum hemorrhage?', 'Uterine atony', 'Vaginal tear', 'Retained placenta', 'Coagulopathy', 'a', 'Uterine atony (failure of uterus to contract) is the most common cause of postpartum hemorrhage.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which lab value indicates acute kidney injury?', 'BUN 10 mg/dL', 'Creatinine 2.5 mg/dL', 'GFR 120 mL/min', 'BUN/Creatinine ratio 10:1', 'b', 'Elevated creatinine (>1.2 mg/dL) indicates impaired kidney function. AKI is diagnosed by rapid rise in creatinine.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the priority nursing intervention for a patient with chest tube?', 'Clamp chest tube during transport', 'Keep drainage system below chest level', 'Strip tubing every hour', 'Empty drainage every shift', 'b', 'Chest tube drainage system must be kept below chest level to prevent backflow of drainage into pleural space.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of shock is characterized by warm, flushed skin?', 'Hypovolemic shock', 'Cardiogenic shock', 'Septic shock (early)', 'Neurogenic shock', 'c', 'Early septic shock presents with warm, flushed skin due to vasodilation. Late septic shock presents with cold, clammy skin.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum sodium?', '115-125 mEq/L', '125-135 mEq/L', '135-145 mEq/L', '145-155 mEq/L', 'c', 'Normal serum sodium is 135-145 mEq/L. Hyponatremia <135, hypernatremia >145.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is a beta-blocker?', 'Lisinopril', 'Metoprolol', 'Amlodipine', 'Hydrochlorothiazide', 'b', 'Metoprolol is a beta-1 selective blocker used for hypertension, angina, and heart failure.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common complication of diabetes mellitus?', 'Diabetic ketoacidosis', 'Cardiovascular disease', 'Nephropathy', 'Retinopathy', 'b', 'Cardiovascular disease is the leading cause of morbidity and mortality in diabetic patients.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is best for post-lumbar puncture?', 'Supine', 'Prone', 'Left lateral', 'Trendelenburg', 'a', 'Supine position for 4-6 hours after lumbar puncture helps prevent post-dural puncture headache.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the Glasgow Coma Scale range?', '1-10', '3-15', '5-20', '0-15', 'b', 'GCS ranges from 3 (deep coma) to 15 (fully awake). It assesses eye, verbal, and motor responses.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which electrolyte is most important for cardiac contractility?', 'Sodium', 'Potassium', 'Calcium', 'Magnesium', 'c', 'Calcium plays a crucial role in cardiac muscle contraction through excitation-contraction coupling.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of small bowel obstruction?', 'Tumor', 'Adhesions', 'Hernia', 'Volvulus', 'b', 'Post-surgical adhesions are the most common cause of small bowel obstruction in developed countries.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which blood product requires cross-matching?', 'Fresh frozen plasma', 'Platelets', 'Packed red blood cells', 'Cryoprecipitate', 'c', 'PRBCs require ABO and Rh cross-matching to prevent transfusion reactions.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum calcium?', '6.5-8.5 mg/dL', '8.5-10.5 mg/dL', '10.5-12.5 mg/dL', '12.5-14.5 mg/dL', 'b', 'Normal serum calcium is 8.5-10.5 mg/dL. Hypocalcemia <8.5, hypercalcemia >10.5.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which assessment finding indicates increased intracranial pressure?', 'Pinpoint pupils', 'Bradycardia', 'Cushing''s triad', 'Hypotension', 'c', 'Cushing''s triad (hypertension, bradycardia, irregular respirations) indicates increased ICP.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common type of stroke?', 'Hemorrhagic', 'Ischemic', 'Embolic', 'Thrombotic', 'b', 'Ischemic stroke accounts for approximately 87% of all strokes. Hemorrhagic stroke accounts for 13%.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is a loop diuretic?', 'Hydrochlorothiazide', 'Spironolactone', 'Furosemide', 'Mannitol', 'c', 'Furosemide (Lasix) is a loop diuretic that acts on the ascending loop of Henle to inhibit sodium reabsorption.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum creatinine?', '0.2-0.6 mg/dL', '0.6-1.2 mg/dL', '1.2-2.0 mg/dL', '2.0-3.0 mg/dL', 'b', 'Normal serum creatinine is 0.6-1.2 mg/dL. Elevated levels indicate impaired kidney function.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is used for thyroid surgery?', 'Supine with neck extended', 'Fowler''s position', 'Trendelenburg', 'Lithotomy', 'a', 'Supine with neck extended (hyperextended) provides optimal access to the thyroid gland during surgery.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common symptom of urinary tract infection?', 'Fever', 'Dysuria', 'Hematuria', 'Flank pain', 'b', 'Dysuria (painful urination) is the most common symptom of UTI, along with frequency and urgency.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of diet is recommended for chronic kidney disease?', 'High protein, high potassium', 'Low protein, low potassium', 'High protein, low sodium', 'Low carbohydrate, high fat', 'b', 'CKD patients need low protein to reduce kidney workload and low potassium to prevent hyperkalemia.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the priority in treating anaphylaxis?', 'Call for help', 'Administer epinephrine', 'Start IV fluids', 'Apply oxygen', 'b', 'Epinephrine is the first-line treatment for anaphylaxis and should be administered immediately.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which cranial nerve is responsible for vision?', 'CN I (Olfactory)', 'CN II (Optic)', 'CN III (Oculomotor)', 'CN IV (Trochlear)', 'b', 'CN II (Optic nerve) is responsible for vision. It is tested using a Snellen chart or visual field examination.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common complication of cirrhosis?', 'Hepatic encephalopathy', 'Portal hypertension', 'Ascites', 'Esophageal varices', 'c', 'Ascites is the most common complication of cirrhosis, caused by portal hypertension and hypoalbuminemia.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is an ACE inhibitor?', 'Metoprolol', 'Lisinopril', 'Amlodipine', 'Losartan', 'b', 'Lisinopril is an ACE inhibitor that blocks the conversion of angiotensin I to angiotensin II.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum magnesium?', '1.3-2.1 mEq/L', '2.1-3.0 mEq/L', '3.0-4.0 mEq/L', '0.5-1.3 mEq/L', 'a', 'Normal serum magnesium is 1.3-2.1 mEq/L. Hypomagnesemia <1.3, hypermagnesemia >2.1.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of isolation is needed for Clostridium difficile?', 'Airborne', 'Droplet', 'Contact', 'Standard', 'c', 'C. diff requires contact isolation with gloves and gown. Alcohol-based hand sanitizers are ineffective; hand washing with soap and water is required.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of community-acquired pneumonia?', 'Haemophilus influenzae', 'Mycoplasma pneumoniae', 'Streptococcus pneumoniae', 'Chlamydia pneumoniae', 'c', 'Streptococcus pneumoniae is the most common cause of community-acquired pneumonia.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is best for a patient with hemorrhoids?', 'Supine', 'Prone', 'Left lateral', 'Knee-chest', 'd', 'Knee-chest position provides best exposure for rectal examination and hemorrhoid treatment.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of WBC count?', '2,000-5,000/mmÂ³', '4,000-11,000/mmÂ³', '11,000-15,000/mmÂ³', '15,000-20,000/mmÂ³', 'b', 'Normal WBC count is 4,000-11,000/mmÂ³. Leukocytosis >11,000 indicates infection or inflammation.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which electrolyte imbalance causes Trousseau''s sign?', 'Hyperkalemia', 'Hypocalcemia', 'Hyponatremia', 'Hypermagnesemia', 'b', 'Trousseau''s sign (carpopedal spasm with BP cuff inflation) indicates hypocalcemia.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common type of hernia?', 'Femoral hernia', 'Incisional hernia', 'Inguinal hernia', 'Umbilical hernia', 'c', 'Inguinal hernia is the most common type, accounting for 75% of all abdominal wall hernias.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is used to treat opioid addiction?', 'Naloxone', 'Methadone', 'Flumazenil', 'Naltrexone', 'b', 'Methadone is a long-acting opioid agonist used for maintenance therapy in opioid addiction.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of platelet count?', '50,000-150,000/mmÂ³', '150,000-450,000/mmÂ³', '450,000-750,000/mmÂ³', '750,000-1,000,000/mmÂ³', 'b', 'Normal platelet count is 150,000-450,000/mmÂ³. Thrombocytopenia <150,000 increases bleeding risk.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which assessment finding is most concerning in a post-op patient?', 'Pain 4/10', 'Temperature 37.5Â°C', 'Urine output 20 mL/hour', 'Heart rate 88 bpm', 'c', 'Urine output <30 mL/hour indicates possible hypovolemia or renal impairment requiring immediate attention.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of hyperthyroidism?', 'Thyroiditis', 'Graves'' disease', 'Toxic nodular goiter', 'Pituitary adenoma', 'b', 'Graves'' disease is the most common cause of hyperthyroidism, an autoimmune disorder stimulating TSH receptors.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of shock is caused by pump failure?', 'Hypovolemic', 'Cardiogenic', 'Distributive', 'Obstructive', 'b', 'Cardiogenic shock results from pump failure (e.g., MI, cardiomyopathy) leading to inadequate cardiac output.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum bilirubin?', '0.1-0.3 mg/dL', '0.3-1.0 mg/dL', '1.0-2.0 mg/dL', '2.0-3.0 mg/dL', 'b', 'Normal total bilirubin is 0.3-1.0 mg/dL. Jaundice becomes clinically apparent at >2.5 mg/dL.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is used for a patient with suspected appendicitis?', 'Supine with legs extended', 'Left lateral with legs flexed', 'Supine with right leg flexed', 'Prone', 'c', 'Patients with appendicitis often lie supine with right hip flexed to relieve tension on the inflamed appendix.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common complication of measles?', 'Encephalitis', 'Pneumonia', 'Otitis media', 'Diarrhea', 'c', 'Otitis media is the most common complication of measles, occurring in 5-15% of cases.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is a calcium channel blocker?', 'Metoprolol', 'Amlodipine', 'Lisinopril', 'Losartan', 'b', 'Amlodipine is a calcium channel blocker that inhibits calcium entry into vascular smooth muscle, causing vasodilation.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum albumin?', '2.5-3.5 g/dL', '3.5-5.0 g/dL', '5.0-6.5 g/dL', '1.5-2.5 g/dL', 'b', 'Normal serum albumin is 3.5-5.0 g/dL. Low albumin indicates malnutrition or liver disease.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of incontinence is involuntary urine loss with coughing?', 'Urge incontinence', 'Stress incontinence', 'Overflow incontinence', 'Functional incontinence', 'b', 'Stress incontinence is urine leakage with increased intra-abdominal pressure (coughing, sneezing, laughing).', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of chronic pancreatitis?', 'Alcohol abuse', 'Gallstones', 'Hypertriglyceridemia', 'Autoimmune', 'a', 'Chronic alcohol abuse is the most common cause of chronic pancreatitis.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which lab value indicates dehydration?', 'Low BUN', 'Elevated hematocrit', 'Low serum sodium', 'Low urine specific gravity', 'b', 'Elevated hematocrit and BUN indicate hemoconcentration from dehydration.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the priority intervention for a patient with seizure?', 'Restrain the patient', 'Insert airway', 'Protect from injury', 'Administer oxygen', 'c', 'Protecting the patient from injury is the priority during a seizure. Never restrain or insert anything in the mouth.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is an anticoagulant?', 'Aspirin', 'Clopidogrel', 'Warfarin', 'Ticagrelor', 'c', 'Warfarin is an anticoagulant that inhibits vitamin K-dependent clotting factors. Aspirin and clopidogrel are antiplatelets.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum chloride?', '90-95 mEq/L', '95-105 mEq/L', '105-115 mEq/L', '115-125 mEq/L', 'b', 'Normal serum chloride is 95-105 mEq/L. Chloride follows sodium to maintain electroneutrality.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of fracture is most common in elderly with osteoporosis?', 'Compound fracture', 'Hip fracture', 'Greenstick fracture', 'Comminuted fracture', 'b', 'Hip fracture is most common in elderly osteoporotic patients, often from low-impact falls.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common symptom of gastroesophageal reflux disease?', 'Dysphagia', 'Heartburn', 'Regurgitation', 'Chest pain', 'b', 'Heartburn (pyrosis) is the most common symptom of GERD, a burning sensation behind the sternum.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is best for a patient with ascites?', 'Supine', 'Fowler''s', 'Prone', 'Trendelenburg', 'b', 'Fowler''s or semi-Fowler''s position helps patients with ascites breathe more easily by reducing pressure on the diaphragm.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum phosphorus?', '1.5-2.5 mg/dL', '2.5-4.5 mg/dL', '4.5-6.5 mg/dL', '6.5-8.5 mg/dL', 'b', 'Normal serum phosphorus is 2.5-4.5 mg/dL. Hypophosphatemia <2.5, hyperphosphatemia >4.5.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which assessment finding indicates respiratory alkalosis?', 'Decreased pH, increased CO2', 'Increased pH, decreased CO2', 'Decreased pH, decreased HCO3', 'Increased pH, increased HCO3', 'b', 'Respiratory alkalosis shows increased pH and decreased CO2 from hyperventilation.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common cause of end-stage renal disease?', 'Glomerulonephritis', 'Hypertension', 'Diabetes mellitus', 'Polycystic kidney disease', 'c', 'Diabetes mellitus is the leading cause of ESRD, followed by hypertension.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which medication is a proton pump inhibitor?', 'Ranitidine', 'Famotidine', 'Omeprazole', 'Metoclopramide', 'c', 'Omeprazole is a PPI that irreversibly inhibits the H+/K+ ATPase pump in gastric parietal cells.', 'easy', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum amylase?', '10-30 U/L', '30-110 U/L', '110-200 U/L', '200-400 U/L', 'b', 'Normal serum amylase is 30-110 U/L. Elevated levels indicate pancreatitis.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which type of shock is characterized by decreased preload?', 'Cardiogenic', 'Hypovolemic', 'Distributive', 'Obstructive', 'b', 'Hypovolemic shock is characterized by decreased preload due to loss of intravascular volume.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the most common symptom of benign prostatic hyperplasia?', 'Hematuria', 'Urinary retention', 'Dysuria', 'Urinary frequency', 'd', 'Urinary frequency, especially nocturia, is an early symptom of BPH due to bladder outlet obstruction.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which position is used for a patient with a bleeding esophageal varices?', 'Supine', 'Trendelenburg', 'Left lateral', 'Fowler''s', 'b', 'Trendelenburg position helps maintain cerebral perfusion in patients with bleeding esophageal varices.', 'hard', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: what is the normal range of serum lipase?', '10-50 U/L', '50-150 U/L', '150-300 U/L', '300-500 U/L', 'b', 'Normal serum lipase is 50-150 U/L. Lipase is more specific than amylase for pancreatitis diagnosis.', 'medium', TRUE),
('Nursing', 'Medical Surgical Nursing', 'In a bedside scenario, choose the best answer: which electrolyte imbalance causes U waves on ECG?', 'Hyperkalemia', 'Hypokalemia', 'Hypercalcemia', 'Hypocalcemia', 'b', 'Hypokalemia causes U waves on ECG, along with ST depression and flattened T waves.', 'hard', TRUE),
